'use strict';

// MODULES //

var isArray = require( '@stdlib/assert-is-array' );
var isObject = require( '@stdlib/assert-is-object' );
var objectKeys = require( '@stdlib/utils-keys' );
var fromEntries = require( '@stdlib/utils-from-entries' );
var map = require( '@stdlib/array-base-map' );


// FUNCTIONS //

/**
* Recursively sorts object keys while preserving array order.
*
* @private
* @param {*} value - input value
* @returns {*} sorted value
*/
function sortValue( value ) {
	var keys;
	if ( isArray( value ) ) {
		return map( value, sortValue );
	}
	if ( isObject( value ) ) {
		keys = objectKeys( value ).sort();
		keys = map( keys, mapKey );
		return ( keys.length ) ? fromEntries( keys ) : {};
	}
	return value;

	/**
	* Callback invoked when mapping object keys.
	*
	* @private
	* @param {string} key - property name
	* @returns {Array} object entry
	*/
	function mapKey( key ) {
		return [ key, sortValue( value[ key ] ) ];
	}
}


// MAIN //

/**
* Serializes a value as canonical, indented JSON with a trailing newline.
*
* @param {*} value - JSON-compatible value
* @returns {string} canonical JSON
*/
function canonicalStringify( value ) {
	return JSON.stringify( sortValue( value ), null, 2 ) + '\n';
}


// EXPORTS //

module.exports = canonicalStringify;
